entries[110744] = { ["name"] = "Göttlicher Stern", ["text"] = "4.5% von Grundmana\nSofort 15 sek. Abklingzeit\nLässt vor Euch einen göttlichen Stern entstehen, der 24 Meter weit fliegt und im Umkreis von 4 Metern um seinen Pfad allen Gegnern 4717 Zauberlichtschaden zufügt sowie alle Verbündeten in diesem Bereich um 1 heilt.\n\nNachdem der Stern sein Ziel erreicht hat, kehrt er zu Euch zurück, fügt dabei Gegnern ebenfalls Schaden zu und heilt Verbündete." }
