entries[110803] = { ["name"] = "Blitzschlagschild", ["text"] = "Sofort\nDer Zaubernde wird von einer reaktiven Blitzbarriere umgeben. Wenn der Zaubernde von einem Nahkampf-, Distanz- oder Zauberangriff getroffen wird, erleidet der Angreifer 434 Naturschaden. Dieser Effekt kann nur einmal alle paar Sekunden auftreten. Hält 10 Min. lang an.\n\nEs kann immer nur einer Eurer Elementarschilde auf einem Ziel gleichzeitig aktiv sein.\n(3.5s Abklingzeit)" }
