entries[112264] = { ["name"] = "Glyphe 'Fallender Rächer'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend 'Zornige Vergeltung' aktiv ist, ist Eure Fallgeschwindigkeit verringert." }
entries[112265] = { ["name"] = "Glyphe 'Rechtschaffener Rückzug'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend der Effekt von 'Gottesschild' aktiv ist, wird die Wirkzeit Eures Ruhesteins um 50% verringert." }
entries[112266] = { ["name"] = "Glyphe 'Klingen des Richters'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Richturteil' stellt eine Axt oder ein Schwert statt einem Hammer dar, wenn Ihr eine entsprechende Waffe angelegt habt." }
entries[112429] = { ["name"] = "Glyphe 'Krähenschmaus'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nKritische Treffer mit Eurer Fähigkeit 'Hinrichten' rufen einen Schwarm Aasvögel herbei." }
entries[112430] = { ["name"] = "Glyphe 'Kochende Wut'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr werdet so wütend, wenn Ihr Euch in einem Wutzustand befindet, dass Ihr Feuer fangt." }
entries[112437] = { ["name"] = "Glyphe 'Schlüpfriges Gebräu'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr mit Eurer Fähigkeit 'Schlüpfriges Gebräu' einen Effekt entfernt, werdet Ihr um 10% Eurer maximalen Gesundheit geheilt." }
entries[112440] = { ["name"] = "Glyphe 'Paralyse'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Paralyse' entfernt nun zusätzlich sämtliche regelmäßigen Schadenseffekte vom Ziel." }
entries[112442] = { ["name"] = "Glyphe 'Lebenskokon'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Lebenskokon' kann nun auch gewirkt werden, wenn Ihr betäubt seid." }
entries[112444] = { ["name"] = "Glyphe 'Karmaberührung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure 'Karmaberührung' hat nun eine Reichweite von 25 Metern." }
entries[112450] = { ["name"] = "Glyphe 'Stieren des Ochsen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch den Zauber 'Stieren des Ochsen'.\n\nStieren des Ochsen\nEure Statue des Schwarzen Ochsen zieht den Hass des Ziels auf sich, verringert dessen Bewegungstempo um 50% und zwingt es, die Statue des Schwarzen Ochsen 8 Sek. lang anzugreifen. Die Statue muss sich innerhalb von 40 Metern vom Ziel befinden.\n\nSetzt voraus, dass Eure Statue des Schwarzen Ochsen aktiv ist." }
entries[112451] = { ["name"] = "Glyphe 'Leben nach dem Tode'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Chance, eine heilende Sphäre zu erzeugen, wenn Ihr einen Gegner getötet habt, der Erfahrung oder Ehre gewährt, um 100%." }
entries[112452] = { ["name"] = "Glyphe 'Sparring'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nKlassen: Mönch\n25\nBenutzen:" }
entries[112454] = { ["name"] = "Glyphe 'Entgiftung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn 'Entgiftung' erfolgreich einen schädlichen Effekt entfernt, wird Euer Ziel zusätzlich um 5% geheilt." }
entries[112457] = { ["name"] = "Glyphe 'Stärkendes Gebräu'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Stärkendes Gebräu' verringert Euren erlittenen Schaden um zusätzlich 5%, erhöht Eure Gesundheit dafür aber um 10% statt um 20%." }
entries[112458] = { ["name"] = "Glyphe 'Schadensumlenkung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n[ Nebelwirker : Außerhalb von Arenen und Schlachtfeldern:\nEuer Zauber 'Erbauung' kostet 10% Mana anstelle des Chi.\n\nInnerhalb von Arenen und Schlachtfeldern: ]Eure Fähigkeit 'Schadensumleitung' kann jetzt auf andere Verbündete angewandt werden, allerdings ist in diesem Fall die Heilung um 50% verringert." }
entries[112460] = { ["name"] = "Glyphe 'Zenflug'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch den Zauber 'Zenflug'. 'Zenflug' setzt voraus, dass Ihr eine Fluglizenz besitzt.\n\nZenflug\nIhr fliegt auf einer meditativen Wolke mit hoher Geschwindigkeit durch die Luft." }
entries[112461] = { ["name"] = "Glyphe 'Wasserrolle'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt 'Rollen' oder 'Chitorpedo' einsetzen, um Euch über Wasser fortzubewegen." }
entries[112462] = { ["name"] = "Glyphe 'Knisternder Tigerblitz'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer visuelle Effekt Eures Zaubers 'Knisternder Jadeblitz' hat nun die Farbe des Weißen Tigers." }
entries[112463] = { ["name"] = "Glyphe 'Fliegender Schlangentritt'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Fliegender Schlangentritt' endet automatisch, wenn Ihr einen Gegner trefft, wodurch der Flächenschadenseffekt und die Verlangsamung ausgelöst werden." }
entries[112464] = { ["name"] = "Glyphe 'Ehre'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr verbeugt Euch nach jedem erfolgreichen Einsatz von 'Berührung des Todes'." }
entries[112465] = { ["name"] = "Glyphe 'Hieb'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr greift immer mit Händen und Füßen an, wenn Ihr 'Hieb' einsetzt, selbst wenn Ihr keine Faustwaffen angelegt habt." }
entries[112466] = { ["name"] = "Glyphe 'Springender Tigertritt'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer visuelle Effekt Eurer Fähigkeit 'Tritt der aufgehenden Sonne' hat nun die Farbe des Weißen Tigers." }
entries[112468] = { ["name"] = "Glyphe 'Geisterrolle'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nGeringe Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt 'Rollen' und 'Chitorpedo' einsetzen, während Ihr Euch tot in Geistergestalt bewegt." }
entries[112469] = { ["name"] = "Glyphe 'Kampfstellung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Geist erscheint nun in Kampfstellung, wenn Ihr 'Transzendenz' einsetzt." }
