entries[112857] = { ["name"] = "Natürliche Einsicht", ["text"] = "Erhöht Euer Maximalmana um 400%." }
entries[112858] = { ["name"] = "Spirituelle Einsicht", ["text"] = "Erhöht Eure Manamenge um 400% und die Trefferchance Eurer Zauber 'Blitzschlag', 'Kettenblitzschlag', 'Lavaeruption' [ Elementarschlag : Elementarschlag ], 'Verhexen' und 'Flammenschock' um 15%." }
entries[112859] = { ["name"] = "Heilige Einsicht", ["text"] = "Erhöht die Wirksamkeit Eurer Heilung um 25% sowie die von 'Wort der Herrlichkeit', 'Ewige Flamme' und 'Licht der Morgendämmerung' um 50%.\n\nErhöht Eure Manamenge um 400%.\n\nGestattet, dass 50% Eurer Manaregeneration durch Willenskraft im Kampf weiterläuft.\n\nErhöht die Trefferchance Eurer Zauber 'Heiliger Schock', 'Richturteil' [ Glyphe 'Mahnende Worte' : 'Mahnende Worte' ]und 'Denunzierung' um 15%.\n\nGewährt Euch außerhalb von Arenen und Schlachtfeldern Trefferwert und Waffenkunde in Höhe von 50% der Willenskraft, die Ihr von Gegenständen oder Effekten bezieht." }
entries[112865] = { ["name"] = "Aggressives Gift", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt einem Gegner 12 Sek. lang alle 2 Sek. 3500 bis 4500 Naturschaden zu." }
entries[112866] = { ["name"] = "Teufelswichtel beschwören", ["text"] = "20% von Grundmana / 20% von Grunddämonischer furor\nWirken in 5 sek.\nBeschwört einen Teufelswichtel, der unter dem Befehl des Hexenmeisters steht.\n\nTeufelswichtel wirken den Distanzzauber 'Teufelsfeuerblitz' [ Wichtel: Meister kauterisieren : können ihren Meister im Verlauf der Zeit heilen ] [ Wichtel: Magie versengen : schädliche Magieeffekte läutern ] . [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]" }
entries[112867] = { ["name"] = "Leerenfürsten beschwören", ["text"] = "25% von Grundmana / 20% von Grunddämonischer furor\nWirken in 5 sek.\nBeschwört einen Leerenfürsten, der unter dem Befehl des Hexenmeisters steht.\n\nLeerenfürsten können schwerem Schaden widerstehen [ Leerwandler: Entwaffnen : Nahkampfangreifer entwaffnen ] [ Leerwandler: Schattenschild : angreifenden Gegnern Schattenschaden zufügen ] [ Leerwandler: Schattenbollwerk : Ihre Gesundheit erhöhen, wenn ihnen der Tod bevorsteht ] [ Leerwandler: Leiden : und Gegner verspotten, die ihren Meister angreifen / . ] [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]" }
entries[112868] = { ["name"] = "Shivarra beschwören", ["text"] = "25% von Grundmana / 20% von Grunddämonischer furor\nWirken in 5 sek.\nBeschwört eine Shivarra, die unter dem Befehl des Hexenmeisters steht.\n\nShivarra sind gefährliche Magier, die den Nahkampf bevorzugen. Sie können [ Sukkubus: Geringe Unsichtbarkeit : unsichtbar werden ] [ Sukkubus: Peitschen : Ziele zurückstoßen ] [ Sukkubus: Geringe Unsichtbarkeit : und ] Gegner mesmerisieren, die dadurch nicht angreifen können. [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]" }
entries[112869] = { ["name"] = "Beobachter beschwören", ["text"] = "25% von Grundmana / 20% von Grunddämonischer furor\nWirken in 5 sek.\nBeschwört einen Beobachter, der unter dem Befehl des Hexenmeisters steht.\n\nBeobachter werden von Magie angezogen [ Teufelsjäger: Zaubersperre : unterbrechen mit ihren optischen Angriffen das Wirken von Zaubern ] und können sich selbst heilen, indem sie auf das gegnerische Ziel wirkende magische Stärkungszauber stehlen. [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]" }
entries[112870] = { ["name"] = "Zornwächter beschwören", ["text"] = "25% von Grundmana / 20% von Grunddämonischer furor\nWirken in 5 sek.\nBeschwört einen Zornwächter, der unter dem Befehl des Hexenmeisters steht.\n\nZornwächter sind mächtige Nahkämpfer, die die erhaltene Heilung des Ziels erheblich verringern [ Teufelswache: Teufelssturm : einen mächtigen Flächenangriff ausführen ] [ Teufelswache: Axtwurf : sowie einen Gegner auf Distanz betäuben ] können und am wirksamsten sind, wenn sie mehreren Gegnern gegenüberstehen." }
