entries[112921] = { ["name"] = "Abyssal beschwören", ["text"] = "12.5% von Grundmana 30 Meter Reichweite\nSofort 10 min Abklingzeit\nBeschwört einen Meteor aus dem Wirbelnden Nether, der allen Gegnern im Zielgebiet 1069 Feuerschaden zufügt und sie 2 Sek. lang betäubt. Aus dem Krater erhebt sich ein Abyssal, der 1 Min. lang unter dem Befehl des Zaubernden steht.\n\nDer Abyssal verursacht schweren Flächenschaden und wird Ziele in der Nähe des Einschlagsortes angreifen." }
entries[112922] = { ["name"] = "Abyssal beschwören", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört einen Meteor aus dem Wirbelnden Nether, der allen Gegnern im Zielgebiet 1069 Feuerschaden zufügt und sie 2 Sek. lang betäubt. Aus dem Krater erhebt sich ein Abyssal, der 1 Min. lang unter dem Befehl des Zaubernden steht.\n\nDer Abyssal verursacht schweren Flächenschaden und wird vorrangig Ziele angreifen, die vom Effekt Eurer Zauber 'Omen der Pein' oder 'Omen der Verdammnis' betroffen sind." }
