entries[112947] = { ["name"] = "Nervenlähmung", ["text"] = "Unbegrenzte Reichweite\nSofort\nErfolgreicher Einsatz von 'Nierenhieb' oder 'Fieser Trick' verringert zusätzlich, nachdem der Effekt dieser Fähigkeiten abgelaufen ist, 6 Sek. lang den verursachten Schaden des Ziels um 50% (25% bei Spielercharakteren) sowie seine hervorgerufene Heilung um 10%." }
entries[112948] = { ["name"] = "Frostbombe", ["text"] = "Ersetzt Magierbombe\n1.25% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek. 10 sek. Abklingzeit\nBringt eine Frostbombe am Ziel an. Nach Ablauf von 4 Sek. explodiert die Bombe und fügt dem primären Ziel 4600 Frostschaden sowie allen anderen Zielen im Umkreis von 10 Metern 1 Frostschaden zu. Alle getroffenen Ziele werden 2 Sek. lang um 70% verlangsamt. Die Zeit bis zur Explosion Eures Zaubers 'Frostbombe' sowie seine Abklingzeit werden durch Euer Tempo verringert. Dieser Zauber ist am stärksten, wenn er 5 oder mehr Ziele bei der Explosion trifft." }
