entries[112996] = { ["name"] = "Rolle der Weisheit", ["text"] = "Wirken in 2 sek. 1 tag Abklingzeit\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Traumtinte (3)\nMeditiert darüber, was Ihr heute erlebt habt, um eine Rolle der Weisheit herzustellen. Dabei könnt Ihr ein Rezept für eine Glyphe entdecken, die Ihr noch nicht kennt.\nRolle der Weisheit\nWird beim Aufheben gebunden\n\"Wird von Schreibern verwendet, um mächtige Objekte zu erstellen.\"" }
entries[112997] = { ["name"] = "Zerschmetternder Hieb", ["text"] = "30 Meter ReichweiteWirken in 1.5 sek. 5 min Abklingzeit\nEin Schlag nach dem Ziel, der dessen Rüstung zerschmettert, 12 Schaden verursacht und seine Rüstung 10 Sek. lang um 20% verringert oder jegliche Unverwundbarkeitseffekte entfernt. Der Einsatz dieser Fähigkeit aktiviert Katzengestalt." }
entries[112998] = { ["name"] = "Schattenblitz", ["text"] = "90 Mana 20 Meter Reichweite\nWirken in 1.3 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Gegner, der 30160 bis 33840 Schattenschaden verursacht." }
entries[112999] = { ["name"] = "Fluch der Pein", ["text"] = "30 Meter Reichweite\nSofort\nVerflucht einen Gegner mit Pein und fügt 18 Sek. lang alle 3 Sek. Schattenschaden zu. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
